// 外部插件运行时保活:插件经 import map 动态 import 宿主 chunk,
// 需要 react / react/jsx-runtime 的完整命名导出;这里逐一定名导入并挂到 globalThis,
// 使 Rollup 无法删除未被应用代码直接引用的导出。
import {
  useState,
  useEffect,
  useRef,
  useMemo,
  useCallback,
  useContext,
  useReducer,
  useLayoutEffect,
  useImperativeHandle,
  useDebugValue,
  useDeferredValue,
  useTransition,
  useId,
  useSyncExternalStore,
  useInsertionEffect,
  createElement,
  cloneElement,
  createContext,
  createRef,
  forwardRef,
  memo,
  lazy,
  Suspense,
  StrictMode,
  Component,
  PureComponent,
  Children,
  isValidElement,
  startTransition,
  act,
  version,
  Fragment as ReactFragment,
  __CLIENT_INTERNALS_DO_NOT_USE_OR_WARN_USERS_THEY_CANNOT_UPGRADE
} from './react'
import { jsx, jsxs, Fragment } from './react-jsx-runtime'

export function keepPluginRuntime(): void {
  ;(globalThis as { __pluginRuntime?: unknown }).__pluginRuntime = {
    useState,
    useEffect,
    useRef,
    useMemo,
    useCallback,
    useContext,
    useReducer,
    useLayoutEffect,
    useImperativeHandle,
    useDebugValue,
    useDeferredValue,
    useTransition,
    useId,
    useSyncExternalStore,
    useInsertionEffect,
    createElement,
    cloneElement,
    createContext,
    createRef,
    forwardRef,
    memo,
    lazy,
    Suspense,
    StrictMode,
    Component,
    PureComponent,
    Children,
    isValidElement,
    startTransition,
    act,
    version,
    __CLIENT_INTERNALS_DO_NOT_USE_OR_WARN_USERS_THEY_CANNOT_UPGRADE,
    Fragment: ReactFragment,
    jsx,
    jsxs
  }
}
